app.get('/users/:id', (req, res) => {
  const userId = parseInt(req.params.id);

  if (isNaN(userId)) {
    throw new ValidationError('User ID must be a number');
  }

  if (userId <= 0) {
    throw new ValidationError('User ID must be a positive number');
  }

  const user = [{ id: 1, name: 'Alice', email: 'alice@example.com' },
                { id: 2, name: 'Bob', email: 'bob@example.com' }]
                .find(u => u.id === userId);

  if (!user) {
    throw new NotFoundError(`User with id ${userId} not found`);
  }

  res.json(user);
});

// Add a route that demonstrates DatabaseError
app.post('/users', (req, res) => {
  // Mock database operation failure
  throw new DatabaseError('Failed to save user to database');
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

