const express = require('express');
const app = express;
const { NotFoundError, ValidationError, DatabaseError } = require('./errors');

// Middleware to parse JSON bodies
app.use(express.json());

app.get('/health', (req, res, next) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    next(new CustomError('Internal server error', 500));
  }
});

app.get('/users', (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    if (users.length === 0) {
      throw new NotFoundError('No users found');
    }

    res.json(users);
  } catch (error) {
    if (error instanceof CustomError) {
      next(error);
    } else {
      next(new CustomError('Internal server error', 500));
    }
  }
});

// GET user by id
app.get('/users/:id', (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    if (isNaN(userId)) {
      throw new ValidationError('Invalid user ID');
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new NotFoundError(`User with id ${userId} not found`);
    }

    res.json(user);
  } catch (error) {
    if (error instanceof CustomError) {
      next(error);
    } else {
      next(new CustomError('Internal server error', 500));
    }
  }
});

// POST new user
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    if (!name || !email) {
      throw new ValidationError('Name and email are required');
    }

    // Simulate database operation
    // In a real app, this would be an actual database call
    const newUser = {
      id: Math.floor(Math.random() * 1000),
      name,
      email
    };

    res.status(201).json(newUser);
  } catch (error) {
    if (error instanceof CustomError) {
      next(error);
    } else {
      next(new DatabaseError('Failed to create user'));
    }
  }
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  // Set defaults
  const statusCode = error.statusCode || 500;
  const status = error.status || 'error';

  // Development error - send stack trace
  if (process.env.NODE_ENV === 'development') {
    res.status(statusCode).json({
      status: status,
      message: error.message,
      stack: error.stack,
      error: error
    });
  } else {
    // Production error - don't leak stack traces
    // Operational errors we can trust to expose message
    // Programming errors we send generic message
    if (error.isOperational) {
      res.status(statusCode).json({
        status: status,
        message: error.message
      });
    } else {
      // Log the error for debugging
      console.error('ERROR 💥', error);

      // Send generic message
      res.status(500).json({
        status: 'error',
        message: 'Something went wrong'
      });
    }
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

